#include <iostream>

int main() {
    int a = 0;
    int b = 0;
    int c = 0;
    int x = 0;

    if (std::cin >> a >> b >> c >> x) {
        // Straight-line evaluation of second-degree polynomial: a*x^2 + b*x + c
        // Step-by-step: ((a * x) * x) + (b * x) + c
        int result = a * x * x + b * x + c;
        int modCheck = result % 10;

        std::cout << "Polynomial result: " << result << "\n";
        std::cout << "Remainder when divided by 10: " << modCheck << "\n";
    }

    return 0;
}

#include <iostream>

int main() {
    int num1 = 0;
    int num2 = 0;

    if (std::cin >> num1 >> num2) {
        if (num1 == num2) {
            std::cout << num1 << " == " << num2 << "\n";
        }
        if (num1 != num2) {
            std::cout << num1 << " != " << num2 << "\n";
        }
        if (num1 < num2) {
            std::cout << num1 << " < " << num2 << "\n";
        }
        if (num1 > num2) {
            std::cout << num1 << " > " << num2 << "\n";
        }
        if (num1 <= num2) {
            std::cout << num1 << " <= " << num2 << "\n";
        }
        if (num1 >= num2) {
            std::cout << num1 << " >= " << num2 << "\n";
        }
    }

    return 0;
}
